/**
 * `scrub` as it was before it was made linear, frozen. It is the oracle of
 * `scrub-differential.test.ts`: the new `scrub` must give the same text for
 * every input. It is quadratic (a run of `a-a-a-…` of 80,000 characters takes
 * 12 seconds), so nothing but that test may call it, and only with short
 * strings. `redactUrl` of `@openpacker/adapter-core` is written out so that a
 * change to it cannot move the oracle. Do not edit this file.
 */
function redactUrl(url: URL): string {
  return `${url.origin}${url.pathname}`;
}

export function legacyScrub(text: string): string {
  return text
    .replace(/\b[a-z][a-z0-9+.-]*:\/\/[^\s'"<>)\]]+/giu, (match) => {
      try {
        const url = new URL(match);
        // A URL with an opaque origin (`socks5://…`) still has a host.
        return url.origin === 'null'
          ? `${url.protocol}//${url.host}${url.pathname}`
          : redactUrl(url);
      } catch {
        return '[url]';
      }
    })
    .replace(
      /\b([\w-]*(?:authorization|token|secret|password|passwd|api[_-]?key))(\s*[:=]\s*)(?:(?:Bearer|Basic)\s+)?[^\s,;'")\]]+/giu,
      (_match, name: string, separator: string) =>
        `${name}${separator}[REDACTED]`,
    )
    .replace(
      /\b(Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{8,}/giu,
      (_match, scheme: string) => `${scheme} [REDACTED]`,
    );
}
